@push('scripts')<script>(function(){var modal=document.getElementById('websiteSystemEditModal'),form=document.getElementById('website-system-edit-form'),name=document.getElementById('website-system-edit-name'),project=document.getElementById('website-system-edit-project');if(!modal)return;$(modal).on('show.bs.modal',function(event){var button=event.relatedTarget;form.action=button.getAttribute('data-action');name.value=button.getAttribute('data-name')||'';project.value=button.getAttribute('data-project-id')||'';});$(modal).on('shown.bs.modal',function(){name.focus();name.select();});})();</script>@endpush
